def orbit(r,c):
    pts={(r,c)}
    changed=True
    while changed:
        changed=False
        for x,y in list(pts):
            for p in [(y,x),(31-x,y),(x,31-y)]:
                u,v=p
                if 0<=u<30 and 0<=v<30 and p not in pts: pts.add(p);changed=True
    return frozenset(pts)
