program='''def transform(grid):
    rows, cols = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    def orbit(start):
        cells = {start}
        pending = [start]
        while pending:
            r, c = pending.pop()
            for point in ((c, r), (31 - r, c), (r, 31 - c)):
                nr, nc = point
                if 0 <= nr < rows and 0 <= nc < cols and point not in cells:
                    cells.add(point)
                    pending.append(point)
        return cells

    for r in range(rows):
        for c in range(cols):
            if (r, c) in seen:
                continue
            cells = orbit((r, c))
            seen.update(cells)
            values = {grid[i][j] for i, j in cells if grid[i][j] != 6}
            value = next(iter(values))
            for i, j in cells:
                out[i][j] = value
    return out
'''
